mapper.select:
SELECT d.department_id, d.department_name, d.manager_name, d.budget as department_budget,
-- 员工统计 COUNT(DISTINCT e.employee_id) as employee_count, COUNT(DISTINCT CASE WHEN e.status = 'ACTIVE' THEN e.employee_id END) as active_employees, COUNT(DISTINCT CASE WHEN e.status = 'INACTIVE' THEN e.employee_id END) as inactive_employees,
-- 薪资统计 IFNULL(salary_stats.total_salary, 0) as total_salary_cost, IFNULL(salary_stats.avg_salary, 0) as avg_salary, IFNULL(salary_stats.max_salary, 0) as max_salary, IFNULL(salary_stats.min_salary, 0) as min_salary,
-- 预算使用率 CASE WHEN d.budget > 0 THEN ROUND((IFNULL(salary_stats.total_salary, 0) / d.budget) * 100, 2) ELSE 0 END as budget_usage_percentage,
-- 项目参与统计 IFNULL(project_stats.project_count, 0) as managed_projects, IFNULL(project_stats.total_project_budget, 0) as managed_project_budget,
-- 绩效评级分布 employee_perf.excellent_count, employee_perf.good_count, employee_perf.average_count, employee_perf.poor_count
FROM department d LEFT JOIN employee e ON d.department_id = e.department_id LEFT JOIN ( SELECT e2.department_id, SUM(s.net_salary) as total_salary, AVG(s.net_salary) as avg_salary, MAX(s.net_salary) as max_salary, MIN(s.net_salary) as min_salary FROM salary s JOIN employee e2 ON s.employee_id = e2.employee_id WHERE s.status = 'PAID'
AND s.pay_date >= #{payDateStart}
AND s.pay_date <= #{payDateEnd}
GROUP BY e2.department_id ) salary_stats ON d.department_id = salary_stats.department_id LEFT JOIN ( SELECT department_id, COUNT(*) as project_count, SUM(budget) as total_project_budget FROM project WHERE status IN ('ACTIVE', 'COMPLETED') GROUP BY department_id ) project_stats ON d.department_id = project_stats.department_id LEFT JOIN ( SELECT e3.department_id, COUNT(CASE WHEN e3.performance_rating = 'EXCELLENT' THEN 1 END) as excellent_count, COUNT(CASE WHEN e3.performance_rating = 'GOOD' THEN 1 END) as good_count, COUNT(CASE WHEN e3.performance_rating = 'AVERAGE' THEN 1 END) as average_count, COUNT(CASE WHEN e3.performance_rating = 'POOR' THEN 1 END) as poor_count FROM employee e3 WHERE e3.status = 'ACTIVE' GROUP BY e3.department_id ) employee_perf ON d.department_id = employee_perf.department_id
AND d.department_id = #{departmentId}
AND d.status = #{departmentStatus}
GROUP BY d.department_id, d.department_name, d.manager_name, d.budget, salary_stats.total_salary, salary_stats.avg_salary, salary_stats.max_salary, salary_stats.min_salary, project_stats.project_count, project_stats.total_project_budget, employee_perf.excellent_count, employee_perf.good_count, employee_perf.average_count, employee_perf.poor_count ORDER BY d.department_id

SELECT p.project_id, p.project_name, p.start_date, p.end_date, p.budget, p.status, d.department_name,
-- 团队统计 IFNULL(team_stats.team_size, 0) as team_size, IFNULL(team_stats.avg_contribution_rate, 0) as avg_contribution_rate,
-- 进度统计 IFNULL(milestone_stats.total_milestones, 0) as total_milestones, IFNULL(milestone_stats.completed_milestones, 0) as completed_milestones, CASE WHEN IFNULL(milestone_stats.total_milestones, 0) > 0 THEN ROUND((IFNULL(milestone_stats.completed_milestones, 0) * 100.0 / IFNULL(milestone_stats.total_milestones, 0)), 2) ELSE 0 END as completion_percentage,
-- 时间分析 DATEDIFF(IFNULL(p.end_date, CURDATE()), p.start_date) as total_duration_days, CASE WHEN p.status = 'COMPLETED' AND p.end_date IS NOT NULL THEN DATEDIFF(p.end_date, p.start_date) WHEN p.status IN ('ACTIVE', 'PLANNING') THEN DATEDIFF(CURDATE(), p.start_date) ELSE 0 END as actual_duration_days,
-- 预算分析 IFNULL(project_expenses.actual_expenses, 0) as actual_expenses, (p.budget - IFNULL(project_expenses.actual_expenses, 0)) as budget_remaining, CASE WHEN p.budget > 0 THEN ROUND((IFNULL(project_expenses.actual_expenses, 0) / p.budget) * 100, 2) ELSE 0 END as budget_usage_percentage,
-- 风险评估 CASE WHEN p.status = 'COMPLETED' THEN 'COMPLETED' WHEN p.end_date < CURDATE() AND p.status != 'COMPLETED' THEN 'OVERDUE' WHEN IFNULL(project_expenses.actual_expenses, 0) > p.budget THEN 'OVER_BUDGET' WHEN p.end_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY) THEN 'HIGH_RISK' WHEN p.end_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY) THEN 'MEDIUM_RISK' ELSE 'LOW_RISK' END as risk_level
FROM project p LEFT JOIN department d ON p.department_id = d.department_id LEFT JOIN ( SELECT project_id, COUNT(*) as team_size, AVG(contribution_rate) as avg_contribution_rate FROM project_employee GROUP BY project_id ) team_stats ON p.project_id = team_stats.project_id LEFT JOIN ( SELECT project_id, COUNT(*) as total_milestones, COUNT(CASE WHEN status = 'COMPLETED' THEN 1 END) as completed_milestones FROM project_milestone GROUP BY project_id ) milestone_stats ON p.project_id = milestone_stats.project_id LEFT JOIN ( SELECT project_id, SUM(expense_amount) as actual_expenses FROM project_expense GROUP BY project_id ) project_expenses ON p.project_id = project_expenses.project_id
AND p.project_id = #{projectId}
AND p.department_id = #{departmentId}
AND p.status = #{status}
AND p.end_date < CURDATE() AND p.status != 'COMPLETED'
AND p.end_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY) AND p.status != 'COMPLETED'
AND p.end_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY) AND p.status != 'COMPLETED'
AND p.start_date >= #{startDate}
AND p.end_date <= #{endDate}
ORDER BY CASE WHEN p.end_date < CURDATE() AND p.status != 'COMPLETED' THEN 1 WHEN IFNULL(project_expenses.actual_expenses, 0) > p.budget THEN 2 WHEN p.end_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY) THEN 3 ELSE 4 END, p.start_date DESC

SELECT e.employee_id, e.employee_code, e.name as employee_name, e.position, e.hire_date, e.status, e.performance_rating, d.department_name,
-- 薪资统计 IFNULL(salary_stats.avg_salary, 0) as avg_salary, IFNULL(salary_stats.total_salary, 0) as total_salary_received, IFNULL(salary_stats.pay_periods, 0) as pay_periods, IFNULL(salary_stats.latest_salary, 0) as latest_salary,
-- 项目参与统计 IFNULL(project_stats.project_count, 0) as participated_projects, IFNULL(project_stats.active_projects, 0) as active_projects, IFNULL(project_stats.completed_projects, 0) as completed_projects, IFNULL(project_stats.avg_contribution_rate, 0) as avg_contribution_rate,
-- 工作年限计算 TIMESTAMPDIFF(YEAR, e.hire_date, CURDATE()) as years_of_service, TIMESTAMPDIFF(MONTH, e.hire_date, CURDATE()) as months_of_service,
-- 部门排名 dept_ranking.salary_rank_in_dept, dept_ranking.performance_rank_in_dept,
-- 综合评分 CASE WHEN e.performance_rating = 'EXCELLENT' THEN 95 WHEN e.performance_rating = 'GOOD' THEN 85 WHEN e.performance_rating = 'AVERAGE' THEN 75 WHEN e.performance_rating = 'POOR' THEN 60 ELSE 70 END + CASE WHEN IFNULL(project_stats.project_count, 0) >= 5 THEN 5 WHEN IFNULL(project_stats.project_count, 0) >= 3 THEN 3 WHEN IFNULL(project_stats.project_count, 0) >= 1 THEN 1 ELSE 0 END as comprehensive_score
FROM employee e LEFT JOIN department d ON e.department_id = d.department_id LEFT JOIN ( SELECT employee_id, AVG(net_salary) as avg_salary, SUM(net_salary) as total_salary, COUNT(*) as pay_periods, MAX(net_salary) as latest_salary FROM salary WHERE status = 'PAID'
AND pay_date >= #{salaryDateStart}
AND pay_date <= #{salaryDateEnd}
GROUP BY employee_id ) salary_stats ON e.employee_id = salary_stats.employee_id LEFT JOIN ( SELECT pe.employee_id, COUNT(*) as project_count, COUNT(CASE WHEN p.status = 'ACTIVE' THEN 1 END) as active_projects, COUNT(CASE WHEN p.status = 'COMPLETED' THEN 1 END) as completed_projects, AVG(pe.contribution_rate) as avg_contribution_rate FROM project_employee pe JOIN project p ON pe.project_id = p.project_id GROUP BY pe.employee_id ) project_stats ON e.employee_id = project_stats.employee_id LEFT JOIN ( SELECT e2.employee_id, RANK() OVER (PARTITION BY e2.department_id ORDER BY IFNULL(s2.avg_salary, 0) DESC) as salary_rank_in_dept, RANK() OVER (PARTITION BY e2.department_id ORDER BY CASE WHEN e2.performance_rating = 'EXCELLENT' THEN 4 WHEN e2.performance_rating = 'GOOD' THEN 3 WHEN e2.performance_rating = 'AVERAGE' THEN 2 WHEN e2.performance_rating = 'POOR' THEN 1 ELSE 0 END DESC ) as performance_rank_in_dept FROM employee e2 LEFT JOIN ( SELECT employee_id, AVG(net_salary) as avg_salary FROM salary WHERE status = 'PAID' GROUP BY employee_id ) s2 ON e2.employee_id = s2.employee_id ) dept_ranking ON e.employee_id = dept_ranking.employee_id
AND e.employee_id = #{employeeId}
AND e.department_id = #{departmentId}
AND e.status = #{status}
AND e.performance_rating = #{performanceRating}
AND e.position LIKE CONCAT('%', #{position}, '%')
ORDER BY comprehensive_score DESC, salary_stats.avg_salary DESC
